<?php $this->layout('default'); use Moves\Services\PlatformDirectory as D; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'status' => V::queryString('status')]; $result = D::users($filters, V::queryPage()); ?>
<div class="cms-card"><form class="cms-filters" method="get"><?= V::field('Pesquisar', 'q', $filters['q'], ['type' => 'search']) ?><?= V::field('Situação', 'status', $filters['status'], ['type' => 'select', 'choices' => ['' => 'Todas'] + D::USER_STATUS]) ?><button class="cms-btn">Filtrar</button></form>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhum usuário encontrado.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Usuários"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Situação</th><th>Plano</th><th>Cadastro</th></tr></thead><tbody><?php foreach ($result['rows'] as $u): ?><tr><td><a href="/usuarios/<?= (int) $u['id'] ?>"><?= V::e(trim($u['first_name'] . ' ' . $u['last_name'])) ?></a><?= $u['admin_id'] ? ' ' . V::badge('info', 'Admin') : '' ?></td><td><?= V::e($u['email']) ?></td><td><?= V::badge($u['status'], D::USER_STATUS[$u['status']] ?? $u['status']) ?></td><td><?= V::e($u['plan_name'] ?? '—') ?></td><td><?= V::date($u['created_at'], false) ?></td></tr><?php endforeach; ?></tbody></table></div><?= V::pager($result) ?><?php endif; ?></div>
